        if (slot_id == CLUSTER_SLOTS || slot_cursor != next_owner) {
            int include_owner = !(slot_cursor->flags & slot_filter);
            if (include_owner) {
                int pair_capacity = 2 * slot_cursor->numslots;
                if (!slot_cursor->slot_info_pairs) {
                    slot_cursor->slot_info_pairs = zmalloc(pair_capacity * sizeof(uint16_t));
                }
                serverAssert((slot_cursor->slot_info_pairs_count + 1) < pair_capacity);
                uint16_t range_end = (uint16_t)(slot_id - 1);
                slot_cursor->slot_info_pairs[slot_cursor->slot_info_pairs_count++] = range_start;
                slot_cursor->slot_info_pairs[slot_cursor->slot_info_pairs_count++] = range_end;
            }
            if (slot_id == CLUSTER_SLOTS) {
                break;
            }
            slot_cursor = next_owner;
            range_start = slot_id;
        }
    }

